    }
    if (versionId.present) {
      map['version_id'] = Variable<String>(versionId.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('ActiveDefinitionsCompanion(')
          ..write('context: $context, ')
          ..write('kind: $kind, ')
          ..write('key: $key, ')
          ..write('versionId: $versionId, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

